  static readonly Slot[] Pool=new Slot[8];static int _epoch;static long _serial;static Material _material;static Texture2D _texture;static Color[] _roles;static Color _lightColor;static readonly MaterialPropertyBlock Props=new MaterialPropertyBlock();
  public static string LastFailure{get;private set;}public static int Submitted{get;private set;}public static int Recycled{get;private set;}public static int StaleContacts{get;private set;}
  public static int ActiveCount{get{int n=0;foreach(var s in Pool)if(s!=null&&s.Busy)n++;return n;}}
  public static bool IsFamily(string family)=>family=="fire"||family=="fire_localburst";
  public static bool Eligible(ResolvedCombatFx.Ticket t)=>t!=null&&IsFamily(t.AttackFamily)&&t.Element=="fire";
  public static string Mode(string family)=>family=="fire"?"projectile":family=="fire_localburst"?"localburst":null;
  public static float Lead(ResolvedCombatFx.Ticket t)=>Eligible(t)?(float)FireContinuousGeometry.Lead(Mode(t.AttackFamily)):0;
  static Color Role(JToken token){if(token==null||!ColorUtility.TryParseHtmlString((string)token,out var c))throw new FormatException("invalid fire role");return c.linear;}
  static Vector4 Vector(Color c)=>new Vector4(c.r,c.g,c.b,1);
  public static bool Ready(){
   LastFailure=null;if(!Tween.SchedulingAllowed){LastFailure="fire_flow_scope_cancelled";return false;}
   if(!Stage.CombatWorld||Stage.Camera==null||!Stage.Camera.isActiveAndEnabled){LastFailure="fire_flow_world_camera_unavailable";return false;}
   if(ElementBattleFx.ForceMissingForTest){LastFailure="fire_flow_forced_resource_missing";return false;}
   if(QualitySettings.activeColorSpace!=ColorSpace.Linear){LastFailure="fire_flow_requires_linear_project";return false;}
   if(_material!=null&&_texture!=null)return true;
   var shader=Shader.Find("DeckRogue/FireContinuousFx");var texture=Resources.Load<Texture2D>("Art/fx/fire-continuous-surface-r1");var palette=Resources.Load<TextAsset>("Data/fire-continuous-palette-r1");
   if(shader==null||!shader.isSupported||texture==null||texture.width!=1774||texture.height!=887||palette==null){LastFailure="fire_flow_shader_or_resource_unavailable";return false;}
   try{var j=JObject.Parse(palette.text);var roles=j["roles_srgb"];var colors=new[]{Role(roles?["shadow"]),Role(roles?["primary"]),Role(roles?["edge"]),Role(roles?["core"])};var light=Role(j["scene_light_srgb"]);var material=new Material(shader);
    try{material.SetTexture("_BaseMap",texture);material.SetVector("_RoleShadow",Vector(colors[0]));material.SetVector("_RolePrimary",Vector(colors[1]));material.SetVector("_RoleEdge",Vector(colors[2]));material.SetVector("_RoleCore",Vector(colors[3]));}catch{UnityEngine.Object.Destroy(material);throw;}
    _material=material;_texture=texture;_roles=colors;_lightColor=light;return true;
   }catch(Exception e){LastFailure="fire_flow_palette_invalid:"+e.GetType().Name;return false;}
  }
  static WorldBattleFx.AttackSpec Spec(FireContinuousGeometry.Buffer geometry){bool local=!geometry.IsProjectile;return new WorldBattleFx.AttackSpec(new[]{0f,0f,0f,0f,0f,0f,0f,.080f,(float)FireContinuousGeometry.End(geometry)},1,1,1,_lightColor,_lightColor,.025f,0f,0f){ContractLighting=true,StandardContractPower=true,TargetPeakMultiplier=.35f*(local?62f/55f:1),FloorPeakMultiplier=.12f*(local?22f/20f:1),MaxCombineGroup="fire-continuous-r1",Envelope=age=>(float)FireContinuousGeometry.Light(geometry,age)};}
  static void DestroySet(Set s){if(s==null)return;foreach(var d in s.Draws)if(d?.Mesh!=null)UnityEngine.Object.Destroy(d.Mesh);if(s.Root!=null){s.Root.gameObject.SetActive(false);UnityEngine.Object.Destroy(s.Root.gameObject);}}
  static Set CreateSet(Transform parent,string mode){var root=new GameObject("fire-flow-"+mode).transform;root.SetParent(parent,false);var geometry=FireContinuousGeometry.Create(mode);var set=new Set{Root=root,Geometry=geometry,Draws=new Draw[geometry.Batches.Length],LightSpec=Spec(geometry)};try{for(int i=0;i<set.Draws.Length;i++){var data=geometry.Batches[i];var go=new GameObject("fire-part-"+i);go.transform.SetParent(root,false);var mesh=new Mesh{name="fire-continuous-r1-"+mode+"-"+i};var d=new Draw{Mesh=mesh};set.Draws[i]=d;mesh.MarkDynamic();d.Vertices=new Vector3[data.Vertices.Length];d.UV=new Vector2[data.Vertices.Length];d.Effect=new Vector2[data.Vertices.Length];d.Colors=new Color[data.Vertices.Length];mesh.vertices=d.Vertices;mesh.uv=d.UV;mesh.SetUVs(1,d.Effect);mesh.colors=d.Colors;mesh.triangles=data.Triangles;mesh.bounds=new Bounds(Vector3.zero,new Vector3(8,8,3));go.AddComponent<MeshFilter>().sharedMesh=mesh;d.Renderer=go.AddComponent<MeshRenderer>();d.Renderer.sharedMaterial=_material;d.Renderer.sortingOrder=i;d.Renderer.shadowCastingMode=ShadowCastingMode.Off;d.Renderer.receiveShadows=false;d.Renderer.enabled=false;}root.gameObject.SetActive(false);return set;}catch{DestroySet(set);throw;}}
  static void Retire(Slot s,int v){if(s.Version!=v)return;s.Busy=false;s.Light?.Cancel();s.Light=null;if(s.Root!=null)s.Root.gameObject.SetActive(false);}
  public static void Cancel(){_epoch++;foreach(var s in Pool)if(s!=null){Retire(s,s.Version);s.Version++;}}
  static Slot Acquire(string mode){int limit=GfxQuality.Level==GfxLevel.Low?4:8;Slot s=null;for(int i=0;i<limit;i++){if(Pool[i]==null)Pool[i]=new Slot();if(!Pool[i].Busy||Pool[i].Root==null){s=Pool[i];break;}}if(s==null){s=Pool[0];for(int i=1;i<limit;i++)if(Pool[i].Serial<s.Serial)s=Pool[i];Recycled++;}Retire(s,s.Version);s.Version++;s.Serial=++_serial;if(s.Root==null){DestroySet(s.Projectile);DestroySet(s.Local);s.Projectile=s.Local=null;s.Root=new GameObject("fire-continuous-r1").transform;}
   if(mode=="projectile"){if(s.Projectile==null)s.Projectile=CreateSet(s.Root,mode);s.Active=s.Projectile;}else{if(s.Local==null)s.Local=CreateSet(s.Root,mode);s.Active=s.Local;}if(s.Projectile?.Root!=null)s.Projectile.Root.gameObject.SetActive(mode=="projectile");if(s.Local?.Root!=null)s.Local.Root.gameObject.SetActive(mode=="localburst");return s;
  }
  static bool Current(Slot s,int v,int epoch)=>epoch==_epoch&&s.Version==v&&s.Busy&&s.Root!=null;
  static void DrawAt(Slot s,float age){FireContinuousGeometry.Sample(s.Active.Geometry,age,s.Available);for(int j=0;j<s.Active.Draws.Length;j++){var d=s.Active.Draws[j];var data=s.Active.Geometry.Batches[j];bool visible=false;Vector3 lo=new Vector3(float.MaxValue,float.MaxValue,float.MaxValue),hi=new Vector3(float.MinValue,float.MinValue,float.MinValue);for(int i=0;i<data.Vertices.Length;i++){var p=data.Vertices[i];var v=new Vector3((float)p.X,(float)p.Y,-(float)p.Z);if(!Finite(v))throw new InvalidOperationException("nonfinite_gpu_vertex");d.Vertices[i]=v;d.UV[i]=new Vector2((float)data.UV[i].X,(float)data.UV[i].Y);d.Effect[i]=new Vector2((float)data.Erosion[i],0);float a=(float)data.Alpha[i],gain=(float)data.Gain[i]*(data.Kind==FireContinuousGeometry.SolidKind?s.Particles:s.Emission);var c=data.Kind==FireContinuousGeometry.SolidKind?_roles[data.Role[i]]:Color.white;d.Colors[i]=new Color(c.r*gain,c.g*gain,c.b*gain,a);visible|=a>0;lo=new Vector3(Mathf.Min(lo.x,v.x),Mathf.Min(lo.y,v.y),Mathf.Min(lo.z,v.z));hi=new Vector3(Mathf.Max(hi.x,v.x),Mathf.Max(hi.y,v.y),Mathf.Max(hi.z,v.z));}d.Renderer.enabled=visible;if(!visible)continue;d.Mesh.SetVertices(d.Vertices);d.Mesh.SetUVs(0,d.UV);d.Mesh.SetUVs(1,d.Effect);d.Mesh.SetColors(d.Colors);d.Mesh.bounds=new Bounds((lo+hi)*.5f,hi-lo+Vector3.one*.001f);Props.Clear();Props.SetFloat("_Kind",data.Kind);d.Renderer.SetPropertyBlock(Props);}}
  static void Hide(Slot s){foreach(var d in s.Active.Draws)d.Renderer.enabled=false;}
  static IEnumerator Life(Slot s,int v,int epoch){try{while(Current(s,v,epoch)){if(s.Landed){float age=Time.time-s.Started;if(age>=FireContinuousGeometry.End(s.Active.Geometry))yield break;DrawAt(s,age);}else{float age=Time.time-s.Expected;if(age>=.35f)yield break;if(age<0)DrawAt(s,age);else Hide(s);}yield return null;}}finally{if(epoch==_epoch)Retire(s,v);}}
  static bool Finite(Vector3 p)=>!float.IsNaN(p.x)&&!float.IsNaN(p.y)&&!float.IsNaN(p.z)&&!float.IsInfinity(p.x)&&!float.IsInfinity(p.y)&&!float.IsInfinity(p.z);
  static double Dot(Vector3 a,Vector3 b)=>(double)a.x*b.x+(double)a.y*b.y+(double)a.z*b.z;
  static bool GpuSource(double x)=>!double.IsNaN(x)&&!double.IsInfinity(x)&&Math.Abs(x)<float.MaxValue/16.0;
  public static WorldBattleFx.AttackPlayback Begin(ResolvedCombatFx.Ticket ticket,float? contactAt=null){
   if(!Eligible(ticket)||!ticket.HasWorld||ticket.Outcome!="hit"||ticket.Amount<=0)return null;
   if(contactAt.HasValue&&(float.IsNaN(contactAt.Value)||float.IsInfinity(contactAt.Value))){ticket.RenderFallbackReason="fire_flow_invalid_contact_clock";return null;}
   if(float.IsNaN(ticket.ContactVisibleHeight)||float.IsInfinity(ticket.ContactVisibleHeight)||ticket.ContactVisibleHeight<=0||!Finite(ticket.Position)||!Finite(ticket.Feet)){ticket.RenderFallbackReason="fire_flow_invalid_captured_geometry";return null;}
   var visual=ticket.Visual;float scale=ticket.ContactVisibleHeight*(visual?.Size??1);if(float.IsNaN(scale)||float.IsInfinity(scale)||scale<=0){ticket.RenderFallbackReason="fire_flow_invalid_composed_scale";return null;}
   if(!Ready()){ticket.RenderFallbackReason=LastFailure;return null;}Slot s=null;try{
    string mode=Mode(ticket.AttackFamily);s=Acquire(mode);s.Busy=true;s.Landed=false;s.Mode=mode;s.Height=ticket.ContactVisibleHeight;s.Expected=contactAt??Time.time;s.Available=Mathf.Min((float)FireContinuousGeometry.Lead(mode),Mathf.Max(0,s.Expected-Time.time));s.Size=visual?.Size??1;s.Emission=visual?.Emission??1;s.Particles=visual?.Particles??1;s.LightPower=visual?.Light??1;s.Tier=ticket.Intensity?.Tier;int v=s.Version,epoch=_epoch;
    s.Root.position=ticket.Position;s.Root.rotation=Stage.Camera.transform.rotation;s.Root.localScale=Vector3.one*scale;s.Root.gameObject.SetActive(true);double x=0,y=0,z=0;bool source=ticket.HasBeamOrigin&&Finite(ticket.BeamOrigin);if(source){var delta=ticket.BeamOrigin-ticket.Position;x=Dot(delta,s.Root.rotation*Vector3.right)/scale;y=Dot(delta,s.Root.rotation*Vector3.up)/scale;z=-Dot(delta,s.Root.rotation*Vector3.forward)/scale;source=GpuSource(x)&&GpuSource(y)&&GpuSource(z);}
    FireContinuousGeometry.ConfigureSource(s.Active.Geometry,x,y,z,source);ticket.OutcomeIncomingReason=mode=="localburst"?"target_local_no_delivery":s.Active.Geometry.SourceValid?"captured_world_endpoints":"fire_target_impact_without_flight";if(mode=="projectile"&&!s.Active.Geometry.SourceValid&&ticket.RenderFallbackReason==null)ticket.RenderFallbackReason="fire_flow_source_unavailable_impact_only";
    var captured=s;var playback=new WorldBattleFx.AttackPlayback{Contact=()=>{if(!Current(captured,v,epoch)){StaleContacts++;return false;}if(!Tween.SchedulingAllowed||!Stage.CombatWorld||Stage.Camera==null||!Stage.Camera.isActiveAndEnabled){ticket.RenderFallbackReason="fire_flow_contact_environment_unavailable";Retire(captured,v);return false;}if(captured.Landed)return true;
     try{captured.Landed=true;captured.Started=Time.time;DrawAt(captured,0);if(Stage.ImpactTargetCurrent(ticket.Target,ticket.Impact)){captured.Light=StageFx.BeginContractAttackLight(ticket.Target,ticket.Impact?.Target,epoch,ticket.Position,ticket.Feet,captured.Height,captured.Active.LightSpec,0,false,()=>Current(captured,v,epoch)&&Stage.ImpactTargetCurrent(ticket.Target,ticket.Impact),1f,captured.LightPower,()=>Time.time-captured.Started);captured.Light?.Land();}ticket.AuthoredRenderer="continuous-fire-modes-r1";return true;}catch(Exception e){Retire(captured,v);ticket.RenderFallbackReason="fire_flow_contact_failed:"+e.GetType().Name;return false;}
    },Read=()=>Current(captured,v,epoch)?new{attack=ticket.AttackFamily,renderer="continuous-fire-modes-r1",mode=captured.Mode,flight=captured.Active.Geometry.FlightEnabled,age=captured.Landed?Time.time-captured.Started:Time.time-captured.Expected,landed=captured.Landed,height=captured.Height,size=captured.Size,damageTier=captured.Tier,version=v,serial=captured.Serial,anticipationUsed=captured.Available,visibleEnd=FireContinuousGeometry.End(captured.Active.Geometry),capturedSourceUnaffectedBySize=true}:null};
    Tween.RunPresentation(Life(s,v,epoch));if(!Current(s,v,epoch)){ticket.RenderFallbackReason="fire_flow_scope_cancelled";return null;}Submitted++;return playback;
   }catch(Exception e){if(s!=null)Retire(s,s.Version);ticket.RenderFallbackReason="fire_flow_construction_failed:"+e.GetType().Name;return null;}
  }
 }
